{"path":"src/topics.mjs","content":"export function validPattern(pattern) {
  if (typeof pattern !== 'string') return false;
  const tokens = pattern.split('.');
  return tokens.every((token, i) => token.length > 0 && (token !== '**' || i === tokens.length - 1));
}

export function matchesTopic(pattern, topic) {
  if (!validPattern(pattern) || typeof topic !== 'string') return false;
  const p = pattern.split('.'), t = topic.split('.');
  if (t.some(token => !token || token === '**')) return false;
  for (let i = 0; i < p.length; i++) {
    if (p[i] === '**') return true;
    if (i >= t.length || (p[i] !== '*' && p[i] !== t[i])) return false;
  }
  return p.length === t.length;
}
"}

{"path":"src/subscriptions.mjs","content":"import { matchesTopic, validPattern } from './topics.mjs';

export class SubscriptionRegistry {
  #entries = new Map();
  upsert(value) {
    if (!value || typeof value.id !== 'string' || !value.id.trim() ||
        typeof value.url !== 'string' || !Array.isArray(value.patterns) ||
        !value.patterns.length || !value.patterns.every(validPattern) || !Number.isFinite(value.expiresAt)) {
      throw new TypeError('Invalid subscription');
    }
    let url;
    try { url = new URL(value.url); } catch { throw new TypeError('Invalid subscription URL'); }
    if (!['http:', 'https:'].includes(url.protocol)) throw new TypeError('Invalid subscription URL');
    this.#entries.set(value.id, { id: value.id, url: value.url, patterns: [...value.patterns], expiresAt: value.expiresAt });
  }
  remove(id) { return this.#entries.delete(id); }
  matching(topic, now) {
    return [...this.#entries.values()]
      .filter(s => s.expiresAt > now && s.patterns.some(p => matchesTopic(p, topic)))
      .sort((a, b) => a.id < b.id ? -1 : a.id > b.id ? 1 : 0)
      .map(s => structuredClone(s));
  }
}
"}

{"path":"src/dedupe.mjs","content":"export class RevisionTracker {
  #producers = new Map();
  accept(producer, id, revision) {
    if (typeof producer !== 'string' || !producer.trim() || typeof id !== 'string' || !id.trim() || !Number.isInteger(revision) || revision < 0) throw new TypeError('Invalid revision identity');
    let entries = this.#producers.get(producer);
    if (!entries) this.#producers.set(producer, entries = new Map());
    if (entries.has(id) && entries.get(id) >= revision) return false;
    entries.set(id, revision);
    return true;
  }
}
"}

{"path":"src/retry.mjs","content":"export function retryDelay(attempt, options) {
  const { baseMs, capMs, retryAfterMs = 0 } = options ?? {};
  if (!Number.isInteger(attempt) || attempt < 0 || !Number.isFinite(baseMs) || baseMs <= 0 || !Number.isFinite(capMs) || capMs < baseMs || !Number.isFinite(retryAfterMs) || retryAfterMs < 0) throw new TypeError('Invalid retry options');
  const exponential = attempt >= Math.log2(capMs / baseMs) ? capMs : baseMs * 2 ** attempt;
  return Math.min(capMs, Math.max(exponential, retryAfterMs));
}
"}

{"path":"src/queue.mjs","content":"export class BoundedQueue {
  #items = [];
  #capacity;
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity <= 0) throw new TypeError('Invalid capacity');
    this.#capacity = capacity;
  }
  push(item) {
    if (this.size >= this.#capacity) return false;
    this.#items.push(item);
    return true;
  }
  shift() { return this.#items.shift(); }
  get size() { return this.#items.length; }
}
"}

{"path":"src/transform.mjs","content":"export function sanitize(value, redactedKeys) {
  const keys = new Set(redactedKeys);
  function copy(v) {
    if (v === null || typeof v !== 'object') return v;
    if (Array.isArray(v)) return v.map(copy);
    return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, keys.has(k) ? '[redacted]' : copy(x)]));
  }
  return copy(value);
}
"}

{"path":"src/journal.mjs","content":"import { DatabaseSync } from 'node:sqlite';
import { normalizeEvent } from './envelope.mjs';

export class Journal {
  #db;
  #closed = false;
  constructor(path) {
    this.#db = new DatabaseSync(path);
    this.#db.exec(`PRAGMA journal_mode=WAL; PRAGMA busy_timeout=5000;
      CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, topic TEXT NOT NULL, revision INTEGER NOT NULL, payload TEXT NOT NULL);`);
  }
  record(input) {
    const e = normalizeEvent(input);
    const payload = JSON.stringify(e.payload);
    return this.#db.prepare(`INSERT INTO events (id,topic,revision,payload) VALUES (?,?,?,?)
      ON CONFLICT(id) DO UPDATE SET topic=excluded.topic, revision=excluded.revision, payload=excluded.payload
      WHERE excluded.revision > events.revision`).run(e.id, e.topic, e.revision, payload).changes > 0;
  }
  get(id) {
    const row = this.#db.prepare('SELECT * FROM events WHERE id=?').get(id);
    return row ? { ...row, payload: JSON.parse(row.payload) } : undefined;
  }
  all() {
    return this.#db.prepare('SELECT * FROM events ORDER BY id').all().map(row => ({ ...row, payload: JSON.parse(row.payload) }));
  }
  close() { if (!this.#closed) { this.#db.close(); this.#closed = true; } }
}
"}

{"path":"src/router.mjs","content":"import { normalizeEvent } from './envelope.mjs';
export function routeEvent(input, registry, tracker, now) {
  const event = normalizeEvent(input);
  if (!tracker.accept('webhook', event.id, event.revision)) return [];
  return registry.matching(event.topic, now).map(s => ({ subscriptionId: s.id, url: s.url, event: normalizeEvent(event) }));
}
"}

{"path":"src/dispatcher.mjs","content":"export async function deliverAll(deliveries, send, { concurrency } = {}) {
  if (!Number.isInteger(concurrency) || concurrency <= 0) throw new TypeError('Invalid concurrency');
  const results = new Array(deliveries.length);
  let next = 0;
  async function worker() {
    while (next < deliveries.length) {
      const index = next++;
      try { results[index] = { ok: true, value: await send(deliveries[index]) }; }
      catch (error) { results[index] = { ok: false, error: error instanceof Error ? error.message : String(error) }; }
    }
  }
  await Promise.all(Array.from({ length: Math.min(concurrency, deliveries.length) }, worker));
  return results;
}
"}

{"path":"src/policy.mjs","content":"import { readFileSync } from 'node:fs';
export function loadPolicy(path) {
  let p;
  try { p = JSON.parse(readFileSync(path, 'utf8')); }
  catch (error) { throw new TypeError('Cannot read deployment JSON', { cause: error }); }
  if (!p || !Number.isInteger(p.maxPayloadBytes) || p.maxPayloadBytes <= 0 ||
      !Number.isInteger(p.retryCapMs) || p.retryCapMs <= 0 ||
      typeof p.preferredRegion !== 'string' || !p.preferredRegion.trim() ||
      !Number.isInteger(p.auditRevision) || p.auditRevision < 0) throw new TypeError('Invalid deployment policy');
  const { maxPayloadBytes, retryCapMs, preferredRegion, auditRevision } = p;
  return { maxPayloadBytes, retryCapMs, preferredRegion, auditRevision };
}
"}

{"path":"src/sender.mjs","content":"import { retryDelay } from './retry.mjs';
export function createHttpSender({ fetchImpl, loadCurrentPolicy, wait, maxAttempts = 3 }) {
  if (typeof fetchImpl !== 'function' || typeof loadCurrentPolicy !== 'function' || typeof wait !== 'function' || !Number.isInteger(maxAttempts) || maxAttempts <= 0) throw new TypeError('Invalid sender options');
  return async function send(delivery) {
    const body = JSON.stringify(delivery.event);
    for (let attempt = 0; attempt < maxAttempts; attempt++) {
      const response = await fetchImpl(delivery.url, { method: 'POST', headers: { 'content-type': 'application/json' }, body });
      if (response.ok) return response.json();
      if (!(response.status === 429 || (response.status >= 500 && response.status <= 599)) || attempt === maxAttempts - 1) throw new Error(`HTTP ${response.status}`);
      const policy = await loadCurrentPolicy();
      const raw = response.headers.get('retry-after');
      const seconds = typeof raw === 'string' && /^\d+(?:\.\d+)?$/.test(raw.trim()) ? Number(raw) : 0;
      const retryAfterMs = Number.isFinite(seconds * 1000) ? seconds * 1000 : 0;
      // Policies may cap below the fixed 100ms base; apply that cap after computing.
      const delay = retryDelay(attempt, { baseMs: 100, capMs: Math.max(100, policy.retryCapMs), retryAfterMs });
      await wait(Math.min(policy.retryCapMs, delay));
    }
  };
}
"}

{"path":"src/server.mjs","content":"import { createServer } from 'node:http';
import { normalizeEvent } from './envelope.mjs';
import { routeEvent } from './router.mjs';
import { loadPolicy } from './policy.mjs';

export function createHubServer({ registry, tracker, journal, now = Date.now, configPath }) {
  return createServer(async (req, res) => {
    const reply = (status, value) => { res.writeHead(status, { 'content-type': 'application/json' }); res.end(JSON.stringify(value)); };
    try {
      const limit = configPath ? loadPolicy(configPath).maxPayloadBytes : 65536;
      if (req.method === 'GET' && req.url === '/events') return reply(200, { events: journal.all() });
      if (req.method !== 'POST' || req.url !== '/events') return reply(404, { error: 'Not found' });
      const chunks = [];
      let size = 0;
      for await (const chunk of req) {
        size += chunk.length;
        if (size > limit) {
          reply(413, { error: 'Payload too large' });
          req.resume();
          return;
        }
        chunks.push(chunk);
      }
      let event;
      try { event = normalizeEvent(JSON.parse(Buffer.concat(chunks).toString('utf8'))); }
      catch { return reply(400, { error: 'Invalid JSON event' }); }
      const stored = journal.record(event);
      const deliveries = stored ? routeEvent(event, registry, tracker, now()) : [];
      reply(202, { deliveries });
    } catch { if (!res.headersSent) reply(500, { error: 'Internal server error' }); }
  });
}
"}

